import{_ as a,o as t,c as o,a5 as r}from"./chunks/framework.UjrY2eRK.js";const h=JSON.parse('{"title":"Upgrade and rollback","description":"","frontmatter":{},"headers":[],"relativePath":"operations/upgrades.md","filePath":"operations/upgrades.md","lastUpdated":1788169631000}'),d={name:"operations/upgrades.md"};function n(l,e,i,s,p,c){return t(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="upgrade-and-rollback" tabindex="-1">Upgrade and rollback <a class="header-anchor" href="#upgrade-and-rollback" aria-label="Permalink to &quot;Upgrade and rollback&quot;">​</a></h1><p>Stable releases use immutable <code>vX.Y.Z</code> tags. Avoid automatic container updaters; an operator should back up, upgrade, and verify deliberately.</p><h2 id="upgrade-a-self-hosted-deployment" tabindex="-1">Upgrade a self-hosted deployment <a class="header-anchor" href="#upgrade-a-self-hosted-deployment" aria-label="Permalink to &quot;Upgrade a self-hosted deployment&quot;">​</a></h2><ol><li>Create and retain a full-volume backup. A UI-created gateway snapshot does not protect <code>admin.sqlite</code>.</li><li>Pin <code>TRINITY_PUSH_GATEWAY_VERSION</code> to the new tag or image digest.</li><li>Run <code>docker compose pull</code> and <code>docker compose up --detach</code>.</li><li>Wait for <code>/health</code> and inspect redacted startup and migration logs.</li></ol><p>Startup applies forward-only delivery migrations before opening the HTTP listener and independently validates/applies administration migrations when the feature is enabled. Upgrading a disabled deployment does not create <code>admin.sqlite</code> or require administration secrets. Browser assets and the administration API come from the same image and must never be upgraded independently.</p><h2 id="roll-back" tabindex="-1">Roll back <a class="header-anchor" href="#roll-back" aria-label="Permalink to &quot;Roll back&quot;">​</a></h2><p>Both migration sets preserve a one-version rollback path when the preceding image can safely read the schemas. To roll back, stop the new container, pin the immediately preceding stable image, recreate it, and verify delivery plus administration health and login. The gateway refuses an incompatible newer schema and never downgrades automatically. Rollback beyond one stable version requires restoring a compatible full-volume backup.</p><p>For Cloudflare, retain the preceding Worker release, apply D1 migrations before dependent code, and use the same health and log checks after deployment.</p>',8)])])}const u=a(d,[["render",n]]);export{h as __pageData,u as default};
